SELECT signature_id,manifest_sha256,auth_epoch,governance_epoch FROM signature_record s
WHERE s.project_id=#{projectId} AND s.document_revision=#{documentRevision} AND s.purpose=#{purpose}
ORDER BY s.signed_at DESC LIMIT 1 FOR UPDATE

SELECT COUNT(*) FROM export_manifest e JOIN document_revision_meta d
  ON d.tenant_id=e.tenant_id AND d.project_id=e.project_id AND d.document_revision=e.document_revision
WHERE d.document_id=#{documentId} AND e.document_revision=#{documentRevision}

mapper.update:
UPDATE export_item SET status='SUCCEEDED',object_ref=#{objectRef},artifact_id=#{artifactId},
  validation_ref=#{validationRef},validation_artifact_id=#{validationArtifactId},revision=revision+1,updated_at=#{now}
WHERE export_item_id=#{exportItemId} AND status='VERIFYING' AND revision=#{itemRevision}
  AND object_ref IS NULL AND artifact_id IS NULL AND validation_ref IS NULL AND validation_artifact_id IS NULL

UPDATE export_item SET status='FAILED',validation_ref=#{validationRef},revision=revision+1,updated_at=#{now}
WHERE export_item_id=#{exportItemId} AND status IN ('RUNNING','VERIFYING') AND revision=#{itemRevision}
  AND object_ref IS NULL AND artifact_id IS NULL AND validation_artifact_id IS NULL
